import sys; sys.path.insert(0, base)
results={}
for tf in sorted(glob.glob(base+'/task-*.py')):
    name=os.path.basename(tf)[:-3]
    pj=base+'/'+name+'.json'
    if not os.path.exists(pj): continue
    spec=importlib.util.spec_from_file_location(name, tf)
    m=importlib.util.module_from_spec(spec)
    try:
        spec.loader.exec_module(m)
        ps=json.load(open(pj))
        results[name]=all(m.transform(p['input'])==p['output'] for p in ps)
    except Exception as e:
        results[name]='ERR: '+repr(e)
for k,v in results.items(): print(k, v)
